MAP
    NAME "WCS"
    EXTENT 26.668678 58.339241 26.796582 58.40941
    UNITS DD
    SIZE 800 600
    MAXSIZE 5000
    PROJECTION
        "epsg:4326"
    END
    OUTPUTFORMAT
        NAME "GEOTIFF"
        DRIVER "GDAL/GTiff"
        MIMETYPE "image/tiff"
        IMAGEMODE FLOAT32
        EXTENSION "tif"
    END
    WEB
        METADATA
            "wcs_enable_request" "*"
            "wcs_srs" "EPSG:4326 EPSG:3857"
            "wcs_title" "Example WCS Mapfile"
            "wcs_description" "Test description"
        END
    END
    LAYER
        NAME "dtm"
        EXTENT 655000 6470000 660000 6475000
        STATUS OFF
        TYPE RASTER
        DATA "data/raster/54752_dtm_1m.tif" # Map data: Estonian Land Board 2024
        PROJECTION
            "epsg:3301"
        END
    END
END